events.command:
/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p\\n' | sort && printf '\\n--- tool availability ---\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
mods=['PIL','cv2','numpy','imageio','torch']
for m in mods:
 try:
  x=__import__(m); print(m,'ok',getattr(x,'__version__',''))
 except Exception as e: print(m,'missing',e)
PY"

/bin/bash -lc 'for x in ffmpeg ffprobe python3; do printf "$x: "; command -v "$x" || true; done
python3 - <<'"'PY'
mods=['PIL','cv2','numpy','imageio']
